package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

type PartRec struct {
	LbPart   string // PIC X(8) @0 len=8
	LbRegion string // PIC X(3) @8 len=3
	LbSerial int64  // PIC 9(4) @11 len=4
}

var WsEofFlag string // PIC X len=1 = "N"
var WsLabel string // PIC X(20) len=20 = SPACES
var WsACount int64 // PIC 99 len=2 = 0
var WsTotalA int64 // PIC 999 len=3 = 0
var WsCount int64 // PIC 999 len=3 = 0

var curRec PartRec
var inputLines []string
var inputIdx int
var inputDone bool

func isInputDone() bool {
	return WsEofFlag == "Y"
}

func pow10(n int) int64 {
	p := int64(1)
	for i := 0; i < n; i++ {
		p *= 10
	}
	return p
}

func formatNumeric(v int64, digits int) string {
	m := pow10(digits)
	// keep low-order digits (truncate high-order)
	r := v % m
	if r < 0 {
		r += m
	}
	s := fmt.Sprintf("%0*d", digits, r)
	if len(s) > digits {
		s = s[len(s)-digits:]
	}
	return s
}

func delimitedBySpace(s string) string {
	if i := strings.IndexByte(s, ' '); i >= 0 {
		return s[:i]
	}
	return s
}

func MainPara() {
	WsEofFlag = "N"
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	WsTotalA = 0
	WsCount = 0

	f, err := os.Open("input.dat")
	if err != nil {
		if os.IsNotExist(err) {
			inputLines = nil
		} else {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	} else {
		sc := bufio.NewScanner(f)
		// allow long lines
		const maxCap = 1024 * 1024
		buf := make([]byte, 0, 64*1024)
		sc.Buffer(buf, maxCap)
		for sc.Scan() {
			line := sc.Text()
			// Scanner strips \n and \r\n already (drops \r)
			inputLines = append(inputLines, line)
		}
		f.Close()
		if err := sc.Err(); err != nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
	}
	inputIdx = 0
	ReadPara()
	for !isInputDone() {
		ProcessPara()
	}
	// CLOSE PART-FILE (nothing to do)
	SummaryPara()
}

func ReadPara() {
	if inputIdx >= len(inputLines) {
		WsEofFlag = "Y"
		return
	}
	line := inputLines[inputIdx]
	inputIdx++
	// pad/truncate to 15 bytes
	if len(line) < 15 {
		line = line + strings.Repeat(" ", 15-len(line))
	} else if len(line) > 15 {
		line = line[:15]
	}
	lbPart := line[0:8]
	lbRegion := line[8:11]
	sSerial := line[11:15]
	var serial int64 = 0
	t := strings.TrimSpace(sSerial)
	if t != "" {
		// parse digits; ignore non-digit? assume digits
		var v int64 = 0
		for i := 0; i < len(t); i++ {
			c := t[i]
			if c >= '0' && c <= '9' {
				v = v*10 + int64(c-'0')
			}
		}
		serial = v
	} else {
		serial = 0
	}
	curRec.LbPart = lbPart
	curRec.LbRegion = lbRegion
	curRec.LbSerial = serial
}

func ProcessPara() {
	WsLabel = strings.Repeat(" ", 20)
	WsACount = 0
	// INSPECT LB-PART TALLYING WS-A-COUNT FOR ALL "A"
	var cnt int64 = 0
	for i := 0; i < len(curRec.LbPart); i++ {
		if curRec.LbPart[i] == 'A' {
			cnt++
		}
	}
	WsACount = (WsACount + cnt) % 100
	// STRING ... INTO WS-LABEL
	p1 := delimitedBySpace(curRec.LbRegion)
	p2 := "-"
	p3 := delimitedBySpace(curRec.LbPart)
	p4 := "-"
	p5 := formatNumeric(curRec.LbSerial, 4)
	concat := p1 + p2 + p3 + p4 + p5
	if len(concat) > 20 {
		concat = concat[:20]
	} else if len(concat) < 20 {
		concat = concat + strings.Repeat(" ", 20-len(concat))
	}
	WsLabel = concat
	// INSPECT WS-LABEL REPLACING ALL "0" BY "O"
	WsLabel = strings.ReplaceAll(WsLabel, "0", "O")
	// ADDs with truncation to PIC 999
	WsTotalA = (WsTotalA + WsACount) % 1000
	WsCount = (WsCount + 1) % 1000
	// DISPLAY WS-LABEL " A=" WS-A-COUNT
	out := WsLabel + " A=" + formatNumeric(WsACount, 2) + "\n"
	os.Stdout.WriteString(out)
	ReadPara()
}

func SummaryPara() {
	out := "LABELS: " + formatNumeric(WsCount, 3) + " A-TOTAL: " + formatNumeric(WsTotalA, 3) + "\n"
	os.Stdout.WriteString(out)
}

func main() {
	MainPara()
}
